"""Independent original P1 feasible Ritz endpoints, terminal rejection and dual audit."""
import sys,json,time,shutil
import numpy as np
from scipy import sparse
from scipy.optimize import lsq_linear
from primary_ritz_storage import load as load_ritz
from baseline_registry import ROOT,REPO,ref,dump,sha

def main():
 t=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');records=[];allchecks={}
 for name in ['primaryP1_ritz_feasible1','primaryP1_ritz_feasible2']:
  src=ROOT/'validation/integrated'/name/'summary.json';s=json.loads(src.read_text());c=np.load(REPO/s['output']['path']);par=json.loads((REPO/s['source']['path']).read_text());r=load_ritz(par);V=r['V'];x=c['before_x'];z=c['after_x'];P=sparse.load_npz(REPO/s['physical_P']['path']);A=sparse.load_npz(REPO/s['physical_A']['path']);p=np.load(REPO/s['problem']['path']);eq=np.isfinite(p['upper'])&(p['lower']==p['upper']);ine=~eq;sl=A@z-p['lower'];force=P@z+p['q'];y=c['physical_dual'];res=force+A.T@y;obj=lambda w:float(.5*w@(P@w)+p['q']@w);hist=json.loads((REPO/s['history']['path']).read_text());accept=[h for h in hist if h.get('accepted')];positive=[h for h in accept if h['alpha']>0];zero=[h for h in accept if h['alpha']==0];pr=max(float(np.max(np.maximum(-sl[ine],0))),float(np.max(abs(sl[eq]))));checks=dict(candidate_hash=sha(REPO/s['candidate']['path'])==s['candidate']['SHA256'],source_hash=sha(REPO/s['source']['path'])==s['source']['SHA256'],output_hash=sha(REPO/s['output']['path'])==s['output']['SHA256'],state_reproduced=np.max(abs(z-(x+V@c['coefficients'])))<1e-12,original_force_reproduced=np.max(abs(res-c['physical_residual']))<1e-10,allrow_feasible=pr<1e-10,actual_objective_decreased=obj(z)<obj(x),working_event_count=len(accept)==s['accepted_linear_steps'],no_nonlinear_update=s['actual_support_updates']==0,physical_KKT_rejected=not s['physical_KKT_qualified']);metrics=dict(primal_mm=pr,stationarity_N=float(np.max(abs(res))),gauge_N=float(np.max(abs(y[eq]))),sign_N=float(np.max(np.maximum(y[ine],0))),complementarity_Nmm=float(np.max(abs(sl[ine]*y[ine]))),RootY_gamma_stationarity_N=float(abs(y[2175])),objective_before_Nmm=obj(x),objective_after_Nmm=obj(z),maximum_increment_mm_rad=float(np.max(abs(z-x))),working_acceptance_events=len(accept),positive_alpha_events=len(positive),zero_length_events=len(zero));terminal=None
  if 'terminal_original_direction' in c.files:
   last=hist[-1];d=c['terminal_original_direction'];trial=z+last['alpha']*d;ts=A@trial-p['lower'];tpr=max(float(np.max(np.maximum(-ts[ine],0))),float(np.max(abs(ts[eq]))));terminal=dict(alpha=last['alpha'],allrow_primal_mm=tpr,maximum_increment_mm_rad=float(np.max(abs(last['alpha']*d))),objective_Nmm=obj(trial),violating_original_rows=np.flatnonzero(ine&(ts<-1e-10)).tolist());checks['terminal_direction_reproduced']=np.max(abs(d-V@c['terminal_search_direction']))<1e-12;checks['terminal_primal_reproduced']=abs(tpr-last['original_primal_mm'])<1e-12;checks['terminal_rejection_reproduced']=not last['accepted'] and tpr>=1e-10
  # Independent full-space nonnegative physical pressure recovery, never signed
  # working duals. It is a computed candidate, not an impossibility certificate.
  act=np.union1d(np.flatnonzero(eq),np.flatnonzero(ine&(abs(sl)<1e-10)));Ar=A[act].T.toarray();fit=lsq_linear(Ar,-force,bounds=(np.full(len(act),-np.inf),np.where(ine[act],0.,np.inf)),method='bvls',tol=1e-13,max_iter=200,lsq_solver='exact');yy=np.zeros(len(sl));yy[act]=fit.x;rr=force+A.T@yy;pm=dict(stationarity_N=float(np.max(abs(rr))),gauge_N=float(np.max(abs(yy[eq]))),sign_N=float(np.max(np.maximum(yy[ine],0))),complementarity_Nmm=float(np.max(abs(sl[ine]*yy[ine]))),RootY_gamma_stationarity_N=float(abs(yy[2175])));pm['qualified']=pr<1e-8 and all(v<1e-8 for v in pm.values());checks['independent_physical_recovery_rejected']=not pm['qualified'];f=out/(name+'_physical.npz');np.savez_compressed(f,x=z,physical_dual=yy,residual=rr,active=act);records.append(dict(source=ref(src),checks={k:bool(v) for k,v in checks.items()},original_unit_metrics=metrics,terminal_rejected_proposal=terminal,independent_physical_cone_recovery=pm,recovery_output=ref(f)));allchecks[name]=all(checks.values())
 ok=all(allchecks.values());dump(out/'summary.json',dict(status='ACTUAL_P1_FEASIBLE_RITZ_INDEPENDENT_AUDIT_PASS' if ok else 'ACTUAL_P1_FEASIBLE_RITZ_INDEPENDENT_AUDIT_FAIL',candidate=s['candidate'],verifier=ref(out/'verifier.py'),checks=allchecks,records=records,actual_support_updates=0,accepted_equilibria=0,newly_qualified_system_gate_ids=[],whole_system_release=False,elapsed_s=time.monotonic()-t,limitations=['Endpoint/objective/force/terminal rejection independently verified. Intermediate trajectories are producer records; zero-length working events explicitly separated from positive alpha events.','Signed working duals are not pressures; full-space conic recovery is independently checked and rejected. No nonlinear update/full system or mesh/time certification.']));print(json.dumps(records));raise SystemExit(0 if ok else 2)
if __name__=='__main__':main()
